function posixNormalize(p        )         {
  if (!p) return '.';
  const isAbsolute = p.startsWith('/') || p.startsWith('\\');
  const normalized = p.replace(/\\/g, '/');
  const segments = normalized.split('/');
  const stack           = [];

  for (const seg of segments) {
    if (!seg || seg === '.') {
      continue;
    }
    if (seg === '..') {
      if (stack.length > 0 && stack[stack.length - 1] !== '..') {
        stack.pop();
      } else if (!isAbsolute) {
        stack.push('..');
      }
    } else {
      stack.push(seg);
    }
  }

  let result = stack.join('/');
  if (isAbsolute) {
    result = '/' + result;
  }
  return result || (isAbsolute ? '/' : '.');
}

function posixDirname(p        )         {
  const normalized = posixNormalize(p);
  const lastSlash = normalized.lastIndexOf('/');
  if (lastSlash === -1) {
    return '.';
  }
  if (lastSlash === 0) {
    return '/';
  }
  return normalized.slice(0, lastSlash);
}

function posixJoin(...parts          )         {
  const filtered = parts.filter(Boolean);
  if (filtered.length === 0) return '.';
  return posixNormalize(filtered.join('/'));
}

function isPrivateTermsPath(filePath        )          {
  const parts = filePath.replace(/\\/g, '/').split('/');
  return parts.includes('.private-terms');
}

function normalizeSourcePath(raw        )         {
  let s = raw.trim().split('#')[0].trim();
  s = s.replace(/:\d+(?::\d+)?$/, '').trim();
  s = s.replace(/^\.\//, '');
  return s;
}

function matchesSource(repoFile        , source        )          {
  if (repoFile === source) return true;
  if (source.endsWith('/')) {
    return repoFile.startsWith(source);
  }
  return repoFile.startsWith(source + '/');
}

function getWikiCategoryAndRole(
  wikiRelPath        ,
  coreMap                        
)                                                 {
  if (wikiRelPath === 'SCHEMA.md') {
    return { category: 'core', role: 'schema' };
  }

  // Exact matches
  for (const [role, mappedPath] of Object.entries(coreMap)) {
    if (!mappedPath.endsWith('/')) {
      if (wikiRelPath === mappedPath) {
        if (role === 'tracker' || role === 'risks') {
          return { category: 'tracker', role };
        }
        if (role === 'decisions') {
          return { category: 'decision', role };
        }
        if (role === 'context' || role === 'handoff') {
          return { category: 'agent', role };
        }
        if (
          role === 'index' ||
          role === 'log' ||
          role === 'log-archive' ||
          role === 'troubleshooting' ||
          role === 'glossary'
        ) {
          return { category: 'core', role };
        }
        return { category: 'topic', role };
      }
    }
  }

  // Directory prefix matches (e.g. decisions/, log/)
  for (const [role, mappedPath] of Object.entries(coreMap)) {
    const dirPrefix = mappedPath.endsWith('/') ? mappedPath : mappedPath + '/';
    if (wikiRelPath.startsWith(dirPrefix)) {
      if (role === 'decisions') {
        return { category: 'decision', role };
      }
      if (role === 'log-archive') {
        return { category: 'core', role };
      }
      if (role === 'tracker' || role === 'risks') {
        return { category: 'tracker', role };
      }
      if (role === 'context' || role === 'handoff') {
        return { category: 'agent', role };
      }
      if (
        role === 'index' ||
        role === 'log' ||
        role === 'troubleshooting' ||
        role === 'glossary'
      ) {
        return { category: 'core', role };
      }
      return { category: 'topic', role };
    }
  }

  // Fallback defaults
  if (wikiRelPath.startsWith('project/decisions/') || wikiRelPath.startsWith('decisions/')) {
    return { category: 'decision', role: 'decisions' };
  }
  if (wikiRelPath.startsWith('log/')) {
    return { category: 'core', role: 'log-archive' };
  }

  return { category: 'topic', role: undefined };
}

function isOrphanException(wikiRelPath        , coreMap                        )          {
  if (wikiRelPath === 'SCHEMA.md') return true;
  if (wikiRelPath === (coreMap['index'] || 'index.md') || wikiRelPath === 'index.md') return true;
  if (wikiRelPath === (coreMap['log'] || 'log.md') || wikiRelPath === 'log.md') return true;

  const logArchive = coreMap['log-archive'] || 'log/';
  if (logArchive) {
    const dir = logArchive.endsWith('/') ? logArchive : logArchive + '/';
    if (wikiRelPath.startsWith(dir)) return true;
  }
  if (wikiRelPath.startsWith('log/')) return true;

  return false;
}

function buildWikiCodeGraph(input   
                   
                                                                            
                      
                                               
                           
                                                                              
 )            {
  const normWikiRoot = posixNormalize(input.wikiRoot)
    .replace(/^\.\//, '')
    .replace(/\/+$/, '');

  // 1. Filter out .private-terms pages
  const validPages = input.pages.filter((p) => !isPrivateTermsPath(p.wikiRelPath));

  // 2. Discover coreMap from SCHEMA.md if available
  const schemaPage = validPages.find((p) => p.wikiRelPath === 'SCHEMA.md');
  const schemaConfig = schemaPage ? parseSchemaMarkdown(schemaPage.content) : null;
  const coreMap = { ...DEFAULT_CORE_MAP, ...(schemaConfig?.coreMap || {}) };

  const validPagesByRel = new Map(validPages.map((p) => [p.wikiRelPath, p]));

  // 3. Parse frontmatter, metadata, and normalized sources for each page
                           
                                                                      
                                            
                  
                                
                  
                        
                          
                           
                          
                      
                                
                         
                      
   

  const processedPages                  = [];
  const allNormalizedSources = new Set        ();

  for (const page of validPages) {
    const fm = parseFrontmatter(page.content);

    // Label determination
    let label = fm.fields.title?.trim();
    if (!label) {
      const h1Match = fm.body.match(/^#\s+(.+)$/m);
      if (h1Match) {
        label = h1Match[1].trim();
      }
    }
    if (!label) {
      label = page.wikiRelPath;
    }

    const { category, role } = getWikiCategoryAndRole(page.wikiRelPath, coreMap);
    const confidence = fm.fields.confidence || undefined;
    const sourceCommit = fm.fields.source_commit || undefined;

    const needsReverify =
      /(?:⚠️\s*)?(?:TO[\s_-]+RE-?VERIFY|NOT[\s_-]+VERIFIED)/i.test(page.content) ||
      fm.fields['needs_reverify'] === 'true';

    const pageLint = (input.lintFindings || []).filter(
      (f) => f.wikiRelPath === page.wikiRelPath
    );
    const lintCount = pageLint.length;
    const hasLintError = lintCount > 0;

    // Normalized sources
    const normalizedSources           = [];
    for (const raw of fm.sources || []) {
      const norm = normalizeSourcePath(raw);
      if (norm && !isPrivateTermsPath(norm)) {
        normalizedSources.push(norm);
        allNormalizedSources.add(norm);
      }
    }

    // Drift calculation
    const driftSet = new Set        ();
    const pageChanged = (input.changedFilesByPage || {})[page.wikiRelPath];
    if (Array.isArray(pageChanged)) {
      for (const cf of pageChanged) {
        if (cf && !isPrivateTermsPath(cf)) {
          driftSet.add(cf);
        }
      }
    }

    for (const src of normalizedSources) {
      for (const dirty of input.dirtyRepoFiles || []) {
        if (!isPrivateTermsPath(dirty) && matchesSource(dirty, src)) {
          driftSet.add(dirty);
        }
      }
    }

    const driftFiles = Array.from(driftSet);
    const hasDrift = driftFiles.length > 0;

    processedPages.push({
      page,
      fm,
      label,
      category,
      role,
      confidence,
      sourceCommit,
      needsReverify,
      hasLintError,
      lintCount,
      normalizedSources,
      driftFiles,
      hasDrift,
    });
  }

  // 4. Resolve markdown links and build backlinks
  const backlinks                           = {};
  for (const page of validPages) {
    backlinks[page.wikiRelPath] = [];
  }

  const markdownEdges              = [];
  const seenMarkdownEdges = new Set        ();

  for (const proc of processedPages) {
    const rawLinks = extractMarkdownLinks(proc.fm.body);
    const fromDir = posixDirname(proc.page.wikiRelPath);

    for (const rawLink of rawLinks) {
      let clean = rawLink.split('#')[0].trim();
      if (clean.startsWith('<') && clean.endsWith('>')) {
        clean = clean.slice(1, -1).trim();
      }
      if (!clean) continue;
      if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(clean)) continue;
      if (clean.startsWith('//')) continue;

      const candidates = [
        posixJoin(fromDir, clean),
        posixJoin(fromDir, clean + '.md'),
        posixNormalize(clean),
        posixNormalize(clean + '.md'),
      ];

      let targetRelPath                = null;
      for (const c of candidates) {
        if (validPagesByRel.has(c)) {
          targetRelPath = c;
          break;
        }
      }

      if (targetRelPath && !isPrivateTermsPath(targetRelPath)) {
        const edgeId = `wiki:${proc.page.wikiRelPath}->wiki:${targetRelPath}:markdown-link`;
        if (!seenMarkdownEdges.has(edgeId)) {
          seenMarkdownEdges.add(edgeId);
          markdownEdges.push({
            id: edgeId,
            source: `wiki:${proc.page.wikiRelPath}`,
            target: `wiki:${targetRelPath}`,
            kind: 'markdown-link',
          });

          if (!backlinks[targetRelPath].includes(proc.page.wikiRelPath)) {
            backlinks[targetRelPath].push(proc.page.wikiRelPath);
          }
        }
      }
    }
  }

  // 5. Build source nodes and source edges
  const sourceNodesMap = new Map                   ();
  const sourceEdges              = [];
  const seenSourceEdges = new Set        ();

  for (const proc of processedPages) {
    for (const src of proc.normalizedSources) {
      if (isPrivateTermsPath(src)) continue;

      // If source points to inside wikiRoot and matches a wiki page
      if (normWikiRoot && src.startsWith(normWikiRoot + '/')) {
        const insideWiki = src.slice(normWikiRoot.length + 1);
        if (validPagesByRel.has(insideWiki)) {
          const edgeId = `wiki:${proc.page.wikiRelPath}->wiki:${insideWiki}:source-link`;
          if (!seenSourceEdges.has(edgeId)) {
            seenSourceEdges.add(edgeId);
            sourceEdges.push({
              id: edgeId,
              source: `wiki:${proc.page.wikiRelPath}`,
              target: `wiki:${insideWiki}`,
              kind: 'source-link',
            });
          }
          continue;
        }
      }

      // Repository source file
      const sourceNodeId = `source:${src}`;
      if (!sourceNodesMap.has(sourceNodeId)) {
        // Drift for source node: matches any dirtyRepoFile
        const matchingDirty = (input.dirtyRepoFiles || []).filter(
          (dirty) => !isPrivateTermsPath(dirty) && matchesSource(dirty, src)
        );
        const srcHasDrift = matchingDirty.length > 0;

        sourceNodesMap.set(sourceNodeId, {
          id: sourceNodeId,
          label: src,
          path: src,
          kind: 'source',
          category: 'source',
          hasDrift: srcHasDrift,
          driftFiles: matchingDirty,
          hasLintError: false,
          lintCount: 0,
          needsReverify: false,
          isOrphan: false,
          sizeBytes: 0,
          degree: 0,
        });
      }

      const edgeId = `wiki:${proc.page.wikiRelPath}->${sourceNodeId}:source-link`;
      if (!seenSourceEdges.has(edgeId)) {
        seenSourceEdges.add(edgeId);
        sourceEdges.push({
          id: edgeId,
          source: `wiki:${proc.page.wikiRelPath}`,
          target: sourceNodeId,
          kind: 'source-link',
        });
      }
    }
  }

  // 6. Build wiki nodes
  const wikiNodes              = [];
  for (const proc of processedPages) {
    const isOrphan =
      !isOrphanException(proc.page.wikiRelPath, coreMap) &&
      (backlinks[proc.page.wikiRelPath]?.length || 0) === 0;

    wikiNodes.push({
      id: `wiki:${proc.page.wikiRelPath}`,
      label: proc.label,
      path: proc.page.wikiRelPath,
      kind: 'wiki',
      category: proc.category,
      role: proc.role,
      confidence: proc.confidence,
      sourceCommit: proc.sourceCommit,
      hasDrift: proc.hasDrift,
      driftFiles: proc.driftFiles,
      hasLintError: proc.hasLintError,
      lintCount: proc.lintCount,
      needsReverify: proc.needsReverify,
      isOrphan,
      sizeBytes: proc.page.sizeBytes,
      degree: 0,
    });
  }

  const allNodes              = [...wikiNodes, ...sourceNodesMap.values()];
  const allEdges              = [...markdownEdges, ...sourceEdges];

  // 7. Compute node degrees
  const incidentCount = new Map                ();
  for (const edge of allEdges) {
    incidentCount.set(edge.source, (incidentCount.get(edge.source) || 0) + 1);
    incidentCount.set(edge.target, (incidentCount.get(edge.target) || 0) + 1);
  }
  for (const node of allNodes) {
    node.degree = incidentCount.get(node.id) || 0;
  }

  // 8. Compute uncoveredRepoFiles
  const uncoveredRepoFiles           = [];
  for (const repoFile of input.repoFiles || []) {
    if (isPrivateTermsPath(repoFile)) continue;
    if (normWikiRoot && (repoFile === normWikiRoot || repoFile.startsWith(normWikiRoot + '/'))) {
      continue;
    }

    let covered = false;
    for (const src of allNormalizedSources) {
      if (matchesSource(repoFile, src)) {
        covered = true;
        break;
      }
    }

    if (!covered) {
      uncoveredRepoFiles.push(repoFile);
    }
  }

  return {
    nodes: allNodes,
    edges: allEdges,
    backlinks,
    uncoveredRepoFiles,
  };
}

function filterWikiGraph(
  graph           ,
  options                    
)                                             {
  // 1. Include code sources filtering
  let candidateNodes = options.includeCodeSources
    ? [...graph.nodes]
    : graph.nodes.filter((n) => n.kind !== 'source');

  const candidateNodeIds = new Set(candidateNodes.map((n) => n.id));

  // Eligible edges based on initial node eligibility
  const eligibleEdges = graph.edges.filter(
    (e) => candidateNodeIds.has(e.source) && candidateNodeIds.has(e.target)
  );

  // 2. Focus node & local graph hops BFS
  if (
    options.focusNodeId &&
    options.localGraphHops !== undefined &&
    options.localGraphHops >= 0
  ) {
    if (!candidateNodeIds.has(options.focusNodeId)) {
      return { nodes: [], edges: [] };
    }

    // Undirected BFS over currently eligible edges
    const adj = new Map                  ();
    for (const e of eligibleEdges) {
      if (!adj.has(e.source)) adj.set(e.source, []);
      if (!adj.has(e.target)) adj.set(e.target, []);
      adj.get(e.source) .push(e.target);
      adj.get(e.target) .push(e.source);
    }

    const distances = new Map                ();
    distances.set(options.focusNodeId, 0);
    const queue           = [options.focusNodeId];

    while (queue.length > 0) {
      const current = queue.shift() ;
      const d = distances.get(current) ;
      if (d < options.localGraphHops) {
        const neighbors = adj.get(current) || [];
        for (const nbr of neighbors) {
          if (!distances.has(nbr)) {
            distances.set(nbr, d + 1);
            queue.push(nbr);
          }
        }
      }
    }

    candidateNodes = candidateNodes.filter((n) => distances.has(n.id));
  }

  // 3. Filter by onlyDriftOrErrors
  if (options.onlyDriftOrErrors) {
    candidateNodes = candidateNodes.filter(
      (n) => n.hasDrift || n.hasLintError || n.needsReverify
    );
  }

  // 4. Filter by searchQuery (case-insensitive on label or path)
  if (options.searchQuery && options.searchQuery.trim()) {
    const q = options.searchQuery.trim().toLowerCase();
    candidateNodes = candidateNodes.filter(
      (n) => n.label.toLowerCase().includes(q) || n.path.toLowerCase().includes(q)
    );
  }

  // 5. Final edges between kept nodes
  const finalNodeIds = new Set(candidateNodes.map((n) => n.id));
  const finalEdges = eligibleEdges.filter(
    (e) => finalNodeIds.has(e.source) && finalNodeIds.has(e.target)
  );

  return {
    nodes: candidateNodes,
    edges: finalEdges,
  };
}

// --- End: src/lib/graph-builder.ts ---


// --- Start: src/ui/graph-canvas.ts ---
                                                             

                                            
            
            
             
             
                 
                   
 

                          
                  
                  
                                        
 

class GraphCanvas {
          canvas                   ;
          ctx                          ;
          nodes            = [];
          edges            = [];
          nodeMap                       = new Map();

  // Viewport transform
          zoom = 1.0;
          panX = 0;
          panY = 0;

  // Interaction
          hoveredNode                 = null;
          selectedNodeId                = null;
          draggedNode                 = null;
          isPanning = false;
          startPanX = 0;
          startPanY = 0;
          dragStartX = 0;
          dragStartY = 0;
          didDragMove = false;

  // Simulation physics
          animFrameId                = null;
          alpha = 1.0;
                   alphaDecay = 0.985;
                   minAlpha = 0.003;

          onSelectNode                            ;

  constructor(
    canvas                   ,
    options                                               
  ) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Could not get 2D context from canvas');
    }
    this.ctx = ctx;
    this.onSelectNode = options?.onSelectNode;

    this.bindEvents();
    this.resizeCanvas();
  }

         resizeCanvas()       {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const width = rect.width || 600;
    const height = rect.height || 400;

    this.canvas.width = Math.floor(width * dpr);
    this.canvas.height = Math.floor(height * dpr);
    this.ctx.resetTransform();
    this.ctx.scale(dpr, dpr);

    if (this.panX === 0 && this.panY === 0) {
      this.panX = width / 2;
      this.panY = height / 2;
    }
    this.requestRender();
  }

         setData(rawNodes             , rawEdges             )       {
    const existingPositions = new Map                                                          ();
    for (const n of this.nodes) {
      existingPositions.set(n.id, { x: n.x, y: n.y, vx: n.vx, vy: n.vy });
    }

    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width || 600;
    const height = rect.height || 400;

    this.nodes = rawNodes.map((n, idx) => {
      const existing = existingPositions.get(n.id);
      let radius = 8;
      if (n.category === 'core' && n.role === 'index') {
        radius = 16;
      } else if (n.category === 'core') {
        radius = 12;
      } else if (n.category === 'source') {
        radius = 5;
      } else if (n.category === 'topic') {
        radius = 9;
      } else if (n.category === 'decision') {
        radius = 10;
      } else {
        radius = 7 + Math.min(8, n.degree);
      }

      if (existing) {
        return {
          ...n,
          x: existing.x,
          y: existing.y,
          vx: existing.vx,
          vy: existing.vy,
          radius,
        };
      }

      const angle = (idx / Math.max(1, rawNodes.length)) * 2 * Math.PI;
      const dist = 50 + Math.random() * Math.min(width, height) * 0.35;
      return {
        ...n,
        x: Math.cos(angle) * dist,
        y: Math.sin(angle) * dist,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        radius,
      };
    });

    this.nodeMap.clear();
    for (const n of this.nodes) {
      this.nodeMap.set(n.id, n);
    }

    this.edges = [];
    for (const e of rawEdges) {
      const src = this.nodeMap.get(e.source);
      const tgt = this.nodeMap.get(e.target);
      if (src && tgt) {
        this.edges.push({
          source: src,
          target: tgt,
          kind: e.kind,
        });
      }
    }

    this.alpha = 1.0;
    this.startSimulation();
  }

         selectNode(nodeId               )       {
    this.selectedNodeId = nodeId;
    this.requestRender();
  }

         resetView()       {
    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width || 600;
    const height = rect.height || 400;
    this.zoom = 1.0;
    this.panX = width / 2;
    this.panY = height / 2;
    this.requestRender();
  }

         zoomIn()       {
    this.applyZoom(1.25);
  }

         zoomOut()       {
    this.applyZoom(0.8);
  }

          applyZoom(factor        )       {
    const rect = this.canvas.getBoundingClientRect();
    const centerX = (rect.width || 600) / 2;
    const centerY = (rect.height || 400) / 2;
    const newZoom = Math.max(0.15, Math.min(4.0, this.zoom * factor));
    this.panX = centerX - (centerX - this.panX) * (newZoom / this.zoom);
    this.panY = centerY - (centerY - this.panY) * (newZoom / this.zoom);
    this.zoom = newZoom;
    this.requestRender();
  }

          startSimulation()       {
    if (this.animFrameId !== null) return;

    const tick = () => {
      if (this.alpha > this.minAlpha) {
        this.stepSimulation();
        this.alpha *= this.alphaDecay;
      }
      this.render();

      if (this.alpha > this.minAlpha || this.isPanning || this.draggedNode) {
        this.animFrameId = requestAnimationFrame(tick);
      } else {
        this.animFrameId = null;
      }
    };

    this.animFrameId = requestAnimationFrame(tick);
  }

          requestRender()       {
    if (this.animFrameId === null) {
      this.startSimulation();
    }
  }

          stepSimulation()       {
    const repulsionStrength = 750;
    const springStrength = 0.045;
    const idealSpringLength = 65;
    const centerStrength = 0.015;
    const damping = 0.82;

    // Node repulsion (n-body)
    for (let i = 0; i < this.nodes.length; i++) {
      const a = this.nodes[i];
      for (let j = i + 1; j < this.nodes.length; j++) {
        const b = this.nodes[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        let distSq = dx * dx + dy * dy;
        if (distSq < 1) distSq = 1;
        const dist = Math.sqrt(distSq);

        const force = (repulsionStrength / distSq) * this.alpha;
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;

        if (!a.pinned && a !== this.draggedNode) {
          a.vx -= fx;
          a.vy -= fy;
        }
        if (!b.pinned && b !== this.draggedNode) {
          b.vx += fx;
          b.vy += fy;
        }
      }
    }

    // Edge attraction (springs)
    for (const e of this.edges) {
      const a = e.source;
      const b = e.target;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const displacement = dist - idealSpringLength;
      const force = displacement * springStrength * this.alpha;
      const fx = (dx / dist) * force;
      const fy = (dy / dist) * force;

      if (!a.pinned && a !== this.draggedNode) {
        a.vx += fx;
        a.vy += fy;
      }
      if (!b.pinned && b !== this.draggedNode) {
        b.vx -= fx;
        b.vy -= fy;
      }
    }

    // Gravity pull towards center (0, 0)
    for (const n of this.nodes) {
      if (!n.pinned && n !== this.draggedNode) {
        n.vx -= n.x * centerStrength * this.alpha;
        n.vy -= n.y * centerStrength * this.alpha;

        n.vx *= damping;
        n.vy *= damping;

        n.x += n.vx;
        n.y += n.vy;
      }
    }
  }

          render()       {
    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width || 600;
    const height = rect.height || 400;

    this.ctx.clearRect(0, 0, width, height);

    if (this.nodes.length === 0) {
      this.ctx.save();
      this.ctx.font = '14px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
      this.ctx.fillStyle = '#64748b';
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'middle';
      this.ctx.fillText(
        "No Wiki loaded in this folder — click '📁 Browse...' to select a repo or '+ Init Wiki' to create one",
        width / 2,
        height / 2
      );
      this.ctx.restore();
      return;
    }

    this.ctx.save();

    // Transform view
    this.ctx.translate(this.panX, this.panY);
    this.ctx.scale(this.zoom, this.zoom);

    // Connected neighbors for hover
    const hoverId = this.hoveredNode?.id;
    const selectedId = this.selectedNodeId;
    const hoverNeighborIds = new Set        ();
    if (hoverId) {
      hoverNeighborIds.add(hoverId);
      for (const e of this.edges) {
        if (e.source.id === hoverId) hoverNeighborIds.add(e.target.id);
        if (e.target.id === hoverId) hoverNeighborIds.add(e.source.id);
      }
    }

    // 1. Draw Edges
    for (const e of this.edges) {
      const isIncidentToHover = Boolean(hoverId && (e.source.id === hoverId || e.target.id === hoverId));
      const isIncidentToSelected = Boolean(selectedId && (e.source.id === selectedId || e.target.id === selectedId));
      const isHighlighted = isIncidentToHover || isIncidentToSelected;
      const isDimmed = Boolean(hoverId && !isIncidentToHover);

      this.ctx.beginPath();
      this.ctx.moveTo(e.source.x, e.source.y);
      this.ctx.lineTo(e.target.x, e.target.y);

      if (isHighlighted) {
        this.ctx.strokeStyle = isIncidentToHover ? '#a5b4fc' : '#818cf8';
        this.ctx.lineWidth = 2.2 / this.zoom;
      } else if (isDimmed) {
        this.ctx.strokeStyle = 'rgba(100, 116, 139, 0.08)';
        this.ctx.lineWidth = 0.8 / this.zoom;
      } else if (e.kind === 'source-link') {
        this.ctx.strokeStyle = 'rgba(56, 189, 248, 0.40)';
        this.ctx.lineWidth = 1.5 / this.zoom;
      } else {
        this.ctx.strokeStyle = 'rgba(148, 163, 184, 0.45)';
        this.ctx.lineWidth = 1.5 / this.zoom;
      }
      this.ctx.stroke();
    }

    // 2. Draw Nodes
    for (const n of this.nodes) {
      const isSelected = n.id === this.selectedNodeId;
      const isHovered = n === this.hoveredNode;
      const isDimmed = Boolean(hoverId && !hoverNeighborIds.has(n.id));

      this.ctx.save();
      if (isDimmed) {
        this.ctx.globalAlpha = 0.25;
      }

      // Outer rings (Drift = Orange, Lint = Red, Selected = White)
      if (isSelected) {
        this.ctx.beginPath();
        this.ctx.arc(n.x, n.y, n.radius + 5, 0, 2 * Math.PI);
        this.ctx.strokeStyle = '#ffffff';
        this.ctx.lineWidth = 2.5 / this.zoom;
        this.ctx.stroke();
      }

      if (n.hasDrift) {
        this.ctx.beginPath();
        this.ctx.arc(n.x, n.y, n.radius + (isSelected ? 8 : 4), 0, 2 * Math.PI);
        this.ctx.strokeStyle = '#f97316'; // Obsidian vibrant orange
        this.ctx.lineWidth = 2.5 / this.zoom;
        this.ctx.stroke();
      }

      if (n.hasLintError) {
        this.ctx.beginPath();
        this.ctx.arc(n.x, n.y, n.radius + (isSelected || n.hasDrift ? 9 : 4), 0, 2 * Math.PI);
        this.ctx.strokeStyle = '#ef4444'; // Red alert ring
        this.ctx.lineWidth = 2.5 / this.zoom;
        this.ctx.stroke();
      }

      // Node Body fill
      this.ctx.beginPath();
      this.ctx.arc(n.x, n.y, n.radius, 0, 2 * Math.PI);
      this.ctx.fillStyle = this.getNodeColor(n);
      this.ctx.fill();

      // Subtle border on node
      this.ctx.strokeStyle = isHovered ? '#ffffff' : 'rgba(255, 255, 255, 0.2)';
      this.ctx.lineWidth = 1.0 / this.zoom;
      this.ctx.stroke();

      // Text Label
      const showLabel =
        this.zoom > 0.65 ||
        isHovered ||
        isSelected ||
        n.category === 'core' ||
        n.degree >= 3;

      if (showLabel) {
        const fontSize = Math.max(10, Math.min(13, 11 / Math.sqrt(this.zoom)));
        this.ctx.font = `${fontSize}px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
        this.ctx.fillStyle = isHovered || isSelected ? '#ffffff' : '#cbd5e1';
        this.ctx.textAlign = 'center';
        this.ctx.textBaseline = 'top';
        this.ctx.fillText(n.label, n.x, n.y + n.radius + 3);
      }

      this.ctx.restore();
    }

    this.ctx.restore();
  }

          getNodeColor(n         )         {
    if (n.category === 'source') {
      return '#64748b'; // Slate code file
    }
    if (n.category === 'topic') {
      return '#38bdf8'; // Sky topic
    }
    if (n.category === 'decision') {
      return '#fbbf24'; // Amber decision
    }

    // Core role colors
    switch (n.role) {
      case 'index':
        return '#3b82f6'; // Blue
      case 'log':
      case 'log-archive':
        return '#a855f7'; // Purple
      case 'tracker':
        return '#10b981'; // Emerald
      case 'decisions':
        return '#f59e0b'; // Amber
      case 'risks':
        return '#ef4444'; // Red
      case 'context':
        return '#06b6d4'; // Cyan
      case 'handoff':
        return '#6366f1'; // Indigo
      case 'troubleshooting':
        return '#f43f5e'; // Rose
      case 'glossary':
        return '#14b8a6'; // Teal
      default:
        return '#94a3b8';
    }
  }

          screenToWorld(clientX        , clientY        )                           {
    const rect = this.canvas.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    return {
      x: (x - this.panX) / this.zoom,
      y: (y - this.panY) / this.zoom,
    };
  }

          findNodeAt(worldX        , worldY        )                 {
    // Search in reverse order (top to bottom)
    for (let i = this.nodes.length - 1; i >= 0; i--) {
      const n = this.nodes[i];
      const dx = worldX - n.x;
      const dy = worldY - n.y;
      const hitRadius = n.radius + 4 / this.zoom;
      if (dx * dx + dy * dy <= hitRadius * hitRadius) {
        return n;
      }
    }
    return null;
  }

          bindEvents()       {
    window.addEventListener('resize', () => this.resizeCanvas());

    this.canvas.addEventListener('wheel', (e            ) => {
      e.preventDefault();
      const rect = this.canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const factor = e.deltaY < 0 ? 1.12 : 0.89;
      const newZoom = Math.max(0.15, Math.min(4.0, this.zoom * factor));

      this.panX = mouseX - (mouseX - this.panX) * (newZoom / this.zoom);
      this.panY = mouseY - (mouseY - this.panY) * (newZoom / this.zoom);
      this.zoom = newZoom;
      this.requestRender();
    });

    this.canvas.addEventListener('mousedown', (e            ) => {
      if (e.button !== 0 && e.button !== 1) return; // Left or middle click
      const world = this.screenToWorld(e.clientX, e.clientY);
      const clicked = this.findNodeAt(world.x, world.y);

      this.dragStartX = e.clientX;
      this.dragStartY = e.clientY;
      this.didDragMove = false;

      if (clicked) {
        this.draggedNode = clicked;
        this.alpha = 0.7;
        this.startSimulation();
      } else {
        this.isPanning = true;
        this.startPanX = e.clientX - this.panX;
        this.startPanY = e.clientY - this.panY;
        this.canvas.style.cursor = 'grabbing';
      }
    });

    window.addEventListener('mousemove', (e            ) => {
      const dx = Math.abs(e.clientX - this.dragStartX);
      const dy = Math.abs(e.clientY - this.dragStartY);
      if (dx > 3 || dy > 3) {
        this.didDragMove = true;
      }

      if (this.draggedNode) {
        const world = this.screenToWorld(e.clientX, e.clientY);
        this.draggedNode.x = world.x;
        this.draggedNode.y = world.y;
        this.draggedNode.vx = 0;
        this.draggedNode.vy = 0;
        this.alpha = 0.5;
        this.requestRender();
        return;
      }

      if (this.isPanning) {
        this.panX = e.clientX - this.startPanX;
        this.panY = e.clientY - this.startPanY;
        this.requestRender();
        return;
      }

      // Hover detection
      const world = this.screenToWorld(e.clientX, e.clientY);
      const hit = this.findNodeAt(world.x, world.y);
      if (hit !== this.hoveredNode) {
        this.hoveredNode = hit;
        this.canvas.style.cursor = hit ? 'pointer' : 'default';
        this.requestRender();
      }
    });

    window.addEventListener('mouseup', (e            ) => {
      if (this.draggedNode) {
        const releasedNode = this.draggedNode;
        this.draggedNode = null;
        if (!this.didDragMove && this.onSelectNode) {
          this.selectNode(releasedNode.id);
          this.onSelectNode(releasedNode);
        }
      }

      if (this.isPanning) {
        this.isPanning = false;
        this.canvas.style.cursor = this.hoveredNode ? 'pointer' : 'default';
      }
    });
  }

         destroy()       {
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
  }
}

